import torch

def run(x, bins, min, max):
    return torch.histc(x, bins=bins, min=min, max=max)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = _dtype_from_context(ctx, "x")
    numel = 1
    for extent in shape:
        numel *= extent
    bucket_ids = torch.arange(numel, device=device) % 100
    values = (bucket_ids.to(dtype) + 0.5) * 0.1
    return {"x": values.reshape(shape)}
